  {i->val h=10.0;val p=1000*9.81*h;item(Difficulty.MEDIUM,"هد افزوده پمپ آب 10 m است. افزایش فشار؟","A water pump adds 10 m head. Pressure rise?","Δp=ρgH=1000×9.81×10="+nf(p)+" Pa="+nf(p/1000)+" kPa.","Δp=ρgH="+nf(p/1000)+" kPa.")},
  {i->val v=.5+.1*i;val q=.01*v;item(Difficulty.MEDIUM,"سرعت "+nf(v)+" m/s از سطح 0.01 m² عبور می‌کند. دبی؟","Velocity "+nf(v)+" m/s through area 0.01 m². Flow rate?","Q=AV=.01×"+nf(v)+"="+nf(q)+" m³/s.","Q=AV="+nf(q)+" m³/s.")},
  {i->val vol=.01+.002*i;val fb=1000*9.81*vol;item(Difficulty.MEDIUM,"جسم "+nf(vol)+" m³ آب جابه‌جا می‌کند. نیروی شناوری؟","Body displaces "+nf(vol)+" m³ of water. Buoyancy?","FB=ρgV=1000×9.81×"+nf(vol)+"="+nf(fb)+" N.","FB=ρgV="+nf(fb)+" N.")},
  {i->val l=10.0+2*i;val hf=.02*l/.05*4/19.62;item(Difficulty.HARD,"لوله f=0.02، L="+nf(l)+" m، D=0.05 m و V=2 m/s دارد. افت هد؟","Pipe f=0.02, L="+nf(l)+" m, D=0.05 m, V=2 m/s. Head loss?","hf=f(L/D)V²/(2g)=.02×("+nf(l)+"/.05)×4/19.62="+nf(hf)+" m.","Darcy-Weisbach gives hf="+nf(hf)+" m.")},
